use vstd::prelude::*;

verus! {

    /// remove_front takes a non‐empty vector `a` and returns a new vector
    /// consisting of all but the first element of `a`, preserving order.
    fn remove_front(a: &Vec<i32>) -> (ret: Vec<i32>)
        requires
            a.len() > 0,
        ensures
            // the result has length exactly one less than the input
            ret.len() == a.len() - 1,
        ensures
            // and for each valid index i in `ret`, ret[i] == a[i+1]
            forall |i: usize| i < ret.len() ==> ret[i] == a[i + 1],
    {
        let mut res: Vec<i32> = Vec::new();
        let n = a.len();
        // we will copy elements a[1], a[2], ..., a[n-1] into res
        let mut k: usize = 1;
        while k < n
            invariant
                // k runs from 1 up to n
                k <= n,
            invariant
                // res.len() == k-1
                res.len() + 1 == k,
            invariant
                // and for all j < res.len(), res[j] == a[j+1]
                forall |j: usize| j < res.len() ==> res[j] == a[j + 1],
            decreases
                // each iteration increases k by 1
                n - k,
        {
            // push the k‐th element of a into res
            res.push(a[k]);
            k = k + 1;
        }
        // when k == n, res.len() == n-1 and the above invariants guarantee
        // the correct content
        res
    }

} // end of verus! block

